{"sql":"WITH w AS (
  SELECT * FROM order_lines
  WHERE customer_id = '14646' AND week BETWEEN '2011-W40' AND '2011-W48'
)
SELECT line_type, count(*) AS lines, count(DISTINCT invoice) AS invoices, sum(amount) AS amt, min(order_date) AS d0, max(order_date) AS d1
FROM w GROUP BY line_type","purpose":"统计该客户该时段内销售/取消行数与发票数"}
